insert into public.venues (
  created_by, name, province, district, subdistrict, address,
  latitude, longitude, rating, availability, status, aliases, source_url, verified_at
)
select
  null,
  seed.name,
  seed.province,
  seed.district,
  seed.subdistrict,
  seed.address,
  null,
  null,
  0,
  'unknown',
  'active',
  '{}'::text[],
  seed.source_url,
  now()
from seed
where not exists (
  select 1 from public.venues existing
  where lower(btrim(existing.name)) = lower(btrim(seed.name))
    and (
      existing.province = seed.province
      or public.arena_area(existing.province) = public.arena_area(seed.province)
    )
);
